};
const OTHER='Other business or service';
function norm(v){return String(v??'').normalize('NFKC').toLowerCase().replace(/\s+/g,' ').trim();}
function words(v){return norm(v).normalize('NFD').replace(/\p{M}/gu,'').match(/[\p{L}\p{N}]+/gu)||[];}
function stem(w){return w.length>4&&w.endsWith('ies')?w.slice(0,-3)+'y':w.length>3&&w.endsWith('s')&&!w.endsWith('ss')&&!w.endsWith('us')?w.slice(0,-1):w;}
function phrase(text,value){return (' '+words(text).map(stem).join(' ')+' ').includes(' '+words(value).map(stem).join(' ')+' ');}
function businessMatch(text,c){if(c.business_type!==OTHER)return (categories[c.business_type]||[]).some(t=>phrase(text,t));const ignored=new Set(['and','or','the','business','businesses','company','companies','service','services']);const terms=words(c.niche).filter(w=>!ignored.has(w)).map(stem);const observed=new Set(words(text).map(stem));return terms.length>0&&terms.every(t=>observed.has(t));}
const nyc=['new york city','nyc','manhattan','brooklyn','queens','bronx','staten island','five boroughs','5 boroughs'];
const placeGroups=[['usa','us','united states','united states of america'],['uk','united kingdom','great britain'],['uae','united arab emirates'],['philippines','ph']];
function areaMatch(text,target){const key=words(target).join(' ');if(['new york city','nyc','new york city ny','new york ny'].includes(key))return nyc.some(p=>phrase(text,p));const parts=String(target).split(/[,;]/).map(x=>x.trim()).filter(Boolean);return parts.length>0&&parts.every(p=>{const group=placeGroups.find(g=>g.includes(words(p).join(' ')))||[p];return group.some(t=>phrase(text,t));});}
function parts(v){const m=String(v).match(/^(https?):\/\/([^\/?#]+)([^?#]*)(\?[^#]*)?(?:#.*)?$/i);if(!m)throw Error('Use an http or https website.');return {scheme:m[1].toLowerCase(),host:m[2].toLowerCase(),path:m[3]||'/',query:m[4]||''};}
function url(v){let s=String(v||'').trim();if(!/^https?:\/\//i.test(s))s='https://'+s;const p=parts(s),a=p.host.split(':'),host=a[0];if(p.host.includes('@')||a.length>2||!host.includes('.')||/^[\d.]+$/.test(host)||/\.(local|localhost|internal|test)$/.test(host)||(a[1]&&!['80','443'].includes(a[1])))throw Error('Use a public business website URL.');const q=p.query.slice(1).split('&').filter(x=>x&&!/^utm_/i.test(x)).join('&');return p.scheme+'://'+p.host+p.path+(q?'?'+q:'');}
function domain(u){return parts(u).host.split(':')[0].replace(/^www\./,'');}
function absoluteLink(raw,base){raw=String(raw).trim();if(/^https?:\/\//i.test(raw))return raw;if(raw.startsWith('//'))return 'https:'+raw;if(/^[a-z][a-z0-9+.-]*:/i.test(raw))throw Error('Not a website link.');const b=parts(base);const path=raw.startsWith('/')?raw:b.path.replace(/[^/]*$/,'')+raw;const out=[];for(const part of path.split('/')){if(part==='..')out.pop();else if(part!=='.')out.push(part);}return b.scheme+'://'+b.host+out.join('/');}
function queryValue(u,key){for(const pair of parts(u).query.slice(1).split('&')){const at=pair.indexOf('=');if(at>=0&&decodeURIComponent(pair.slice(0,at))===key)return decodeURIComponent(pair.slice(at+1).replace(/\+/g,' '));}return '';}
function text(p){const m=p?.markdown;return String(typeof m==='string'?m:m?.raw_markdown||p?.cleaned_html?.replace(/<[^>]+>/g,' ')||'').slice(0,40000);}
function links(p){const a=[];for(const group of ['internal','external'])for(const l of p?.links?.[group]||[])a.push(typeof l==='string'?l:l.href);for(const m of String(p?.html||'').matchAll(/href\s*=\s*["']([^"']+)["']/gi))a.push(m[1].replace(/&amp;/g,'&'));return a.filter(Boolean);}
function readable(p){return p?.success&&text(p).trim()&&!/verify you are human|unusual traffic|access denied|challenge-form/i.test(text(p).slice(0,2000));}
function emails(pages,website){const found=new Map();for(const p of pages){for(const m of (text(p)+' '+links(p).join(' ')).matchAll(/\b[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,24}\b/gi)){const email=m[0].toLowerCase();if(/noreply|no-reply|example\.com|sentry|wixpress|mailservice\.com/.test(email))continue;if(!found.has(email))found.set(email,{email,source_url:p.url});}}return [...found.values()].sort((a,b)=>Number(domain('https://'+a.email.split('@')[1])!==domain(website))-Number(domain('https://'+b.email.split('@')[1])!==domain(website)));}
const blocked=['duckduckgo.com','google.com','bing.com','facebook.com','instagram.com','linkedin.com','youtube.com','yelp.com','angi.com','thumbtack.com','homeadvisor.com','indeed.com','yellowpages.com','bbb.org','wikipedia.org','reddit.com','pinterest.com','tiktok.com'];
function baseRow(c,b){return {record_key:domain(b.website),business_name:b.business_name||domain(b.website),website:b.website,business_type:c.niche,location:c.location,public_email:'',email_source_url:'',evidence_json:'[]',opportunity:'',subject:'',introduction_draft:'',follow_up_draft:'',review_status:'NEEDS_REVIEW',contacted_at:null,last_researched_at:new Date().toISOString(),error:'',run_id:c.run_id};}

return $input.all().filter(i=>i.json.record_key).map(({json:r},i)=>{
 const status=String(r.review_status||'NEEDS_REVIEW').toUpperCase();
 const date=r.contacted_at?new Date(r.contacted_at):null;
 const valid=date&&!Number.isNaN(date.valueOf());
 const due=status==='CONTACTED'&&valid?new Date(date.valueOf()+5*86400000):null;
 let evidence=[];try{evidence=JSON.parse(r.evidence_json||'[]');}catch{}
 return {json:{...r,evidence,next_follow_up_at:due?due.toISOString():null,follow_up_due:Boolean(due&&due<=new Date()),message:'Review drafts and contact details before use. Nothing was sent.'},pairedItem:{item:i}};
